// TH16 v1.00a 弹型常量（0–43 已批准复用同值 TH18 槽，source 仍为 th16）。
// 本卡只用 etSprite(0, 7, 2) 的 type 7。
const TH16_RING_BALL2: int = 464;

// th16_s1_w07 — TH16 v1.00a Stage 1 道中波次。
// 源入口：st01.ecl.txt MainSub07:1339-1350（MainLatter:1072 调入）。
// 依赖：GirlD02:806-829（三只共用的敌主脚本）、GirlD02_at:831-892（发射）。
// 源排程：t=0 建首只；t=347 建左右两只；t=407 排程结束。子敌自身 t=60..465 发 6 波，
// t=240 起上升，之后自然离场。卡帧另加 OPENING_BUFFER=120 起始缓冲。

const TIME_LIMIT: int = 2324;
const OPENING_BUFFER: int = 120;

// 源 etAngle 第二角 0.05235988 rad（3°）的 BAM 值。
const DELTA_BAM: int = 546;
const BULLET_COLOR: int = 2;

// 源 GirlD02_at:0874-0889 的一次 etOn：mode10「固定交替层环」。
// 层 q（0 起）整环基角 = alpha ± H(M,q)，环内 ways 颗整周均分；
// 层速按 k=2*((q+1)/2) 成对取值 v(k)=s0+(s1-s0)*k/(M-1)。
// 四个 rank 的层数都是奇数（5/5/7/9），故只用奇数 M 的 H=floor((q+1)/2)*delta。
// 层环是整周对称点集，环内创建序对结果无影响（无逐弹随机/EX）。
sub volley(alpha: angle, ways: int, layers: int, s0: fx, s1: fx) {
    for q in 0..layers {
        var k: int = ((q + 1) / 2) * 2;
        var speed: fx = s0;
        if layers > 1 { speed = s0 + (s1 - s0) * k / (layers - 1); }
        var h: int = ((q + 1) / 2) * DELTA_BAM;
        var base: angle = alpha + (h as angle);
        if q % 2 != 0 { base = alpha - (h as angle); }
        sh_reset(0);
        sh_sprite(0, TH16_RING_BALL2, BULLET_COLOR);
        sh_ring(0, 1);
        sh_aim(0, 0);
        sh_count(0, ways, 1);
        sh_angle(0, base, 0deg);
        sh_speed(0, speed, 0fx);
        sh_fire(0);
    }
}

// 源 GirlD02_at:0831-0892。wait60 后配置，%A=0 起步、每波 +%F0（父敌 F0=±15°）；
// 同一轮两波相距 73，轮尾 83+10；$B=2 的 dec 循环执行 3 轮 → 6 波。
// 难度值取 etCount/etSpeed 的压栈结果：[-1]（后压）为第一参数。
async sub girl_shoot(f0: angle) {
    var ways: int = 16;
    var layers: int = 9;
    var s0: fx = 4fx;
    var s1: fx = 1.6fx;
    var r: int = global(GVAR_RANK);
    if r == RANK_EASY { ways = 4; layers = 5; s0 = 1.3fx; s1 = 1fx; }
    else if r == RANK_NORMAL { ways = 8; layers = 5; s0 = 2fx; s1 = 1.6fx; }
    else if r == RANK_HARD { ways = 12; layers = 7; s0 = 3fx; s1 = 2.4fx; }
    wait(60);
    var alpha: angle = 0deg;
    for i in 0..3 {
        volley(alpha, ways, layers, s0, s1);
        alpha = alpha + f0;
        wait(73);
        volley(alpha, ways, layers, s0, s1);
        alpha = alpha + f0;
        wait(83);
        wait(10);
    }
}

// 源 GirlD02:0806-0829。框：setHurtbox(32,32)/setHitbox(24,24) 走圆形分支取第一值×0.5。
// 运动：moveVel(90°,3) → moveVelTime(60,mode1,90°,0)（二次加速到停）；wait240 后
// moveSpeedTime(120,mode1,-1)（沿 90° 反向 = 向上加速），wait60 后进入无限等待。
// 源 async 延迟与目标 spawn 次帧首跑一致，故不额外补帧。
async sub girl(f0: angle) {
    set_invuln(65535);
    set_hurtbox(16fx);
    set_hitbox(12fx);
    move_vel(0, 90deg, 3fx, EASE_LINEAR);
    move_vel(60, 90deg, 0fx, EASE_QUAD_IN);
    spawn girl_shoot(f0);
    wait(240);
    move_speed(120, -1fx, EASE_QUAD_IN);
    wait(60);
    loop { wait(1000); }
}

// 源 MainSub07:1341-1350。enmCreate 相对 (0,0) 的父位置即绝对坐标；
// %F0 于创建前设置，子敌在创建时继承。
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, -24fx, 2200, 0, 1000, 0, girl(15deg));
    wait(347);
    _ = spawn_enemy(80fx, -24fx, 1800, 0, 1000, 0, girl(-15deg));
    _ = spawn_enemy(-80fx, -24fx, 1800, 0, 1000, 0, girl(15deg));
    wait(60);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
